def frequency_Of_Largest(n, arr):
    """Write a python function to find the frequency of the largest value in a given array."""
    if arr is None or n is None:
        return 0
    if n <= 0:
        return 0
    if len(arr) == 0:
        return 0
    effective = arr[:n]
    if len(effective) == 0:
        return 0
    largest = max(effective)
    return sum(1 for x in effective if x == largest)
